#dim tSC As %Status=$$$OK #dim OrdSelectSnap,OrdIdSnap As EnsLib.SQL.Snapshot #dim debug As %Boolean=0 set debug=$g(^IHCDebugCode(..%ConfigName),0) #dim orddate As %Library.Date
Set OrdSelectSnap=##class(EnsLib.SQL.Snapshot).%New() Set OrdSelectSnap.MaxRowsToGet=-1 $$$TRACE("Order id before select "_pRequest.OrderId) Set tOrdSelectQuery="SELECT ORDERID,TESTID FROM POST.EXTERNALORDERS WHERE ORDERID = ? AND TESTID = ?"
Set tSCSelect = ..Adapter.ExecuteQuery(.OrdSelectSnap,tOrdSelectQuery,pRequest.OrderId,pRequest.TestId) $$$TRACE("Order id select status "_tSCSelect)
Set RetOrdId = "" Set RetTestId = "" If $$$ISOK(tSCSelect) { If OrdSelectSnap.Next() { Set RetOrdId = OrdSelectSnap.GetData(1) Set RetTestId = OrdSelectSnap.GetData(2) } } else { $$$TRACE("Error in executing Select OrderId query") Quit tSCSelect } $$$TRACE("Ret ord id and "_RetOrdId_" inbound orderid "_pRequest.OrderId_"RetTestid "_RetTestId)
$$$TRACE("pRequest.OrderId = " _ pRequest.OrderId)
If ((RetOrdId'=pRequest.OrderId)&&(RetTestId'=pRequest.TestId)) { $$$TRACE("inside if of RetOrdId'=pRequest.OrderId") //Insert the data Set tOrdInsertQuery="insert into POST.EXTERNALORDERS (patientid, firstname, middlename, lastname, dob, sex, orderid, orderdate, physicianname,serviceddate, serviced, active, testid,SOURCENAME) "_ "values(?,?,?,?,?,?,?,?,?,?,?,?,?,?)"
;Set dob = $Replace($Zdate($ZdateH(pRequest.PatientDOB,8),2)," ","-") ;Set ordDate = $Replace($Zdate($ZdateH($Extract(pRequest.OrderDate,1,8),8),2)," ","-")
//set up multidimensional array of parameters set par(1)=pRequest.PatientId set par(2)=pRequest.PatientFirstName set par(3)= pRequest.PatientMidldleName set par(4)=pRequest.PatientLastName set par(5)= pRequest.PatientDOB set par(6)=pRequest.PatientGender set par(7)=pRequest.OrderId set par(8)= pRequest.OrderDate // _" 11:45"
set par(9)=pRequest.PhysicianName set par(10)= pRequest.ServicedDate set par(11)=pRequest.Serviced set par(12)="Y" set:pRequest.IsActive'="" par(12)=pRequest.IsActive set par(13)="EMPTY" set:pRequest.TestId'="" par(13)=pRequest.TestId set par(14)="EMPTY" set:pRequest.SourceName'="" par(14)=pRequest.SourceName set par=14
$$$TRACE(par(1)_" ~~~ "_par(2)_" ~~~ "_par(3)_" ~~~ "_par(4)_" ~~~ "_par(5)_" ~~~ "_par(6)_" ~~~ "_par(7)_" ~~~ "_par(8)_" ~~~ "_par(9)_" ~~~ "_par(10)_" ~~~ "_par(11)_" ~~~ "_par(12)_" ~~~ "_par(13)_" ~~~ "_par(14))
// insert the data into POST DB try { Set tSC =..Adapter.ExecuteUpdateParmArray(.nrows,tOrdInsertQuery,.par) } catch err { $$$TRACE("error in insert: " _ err.Code _ ", " _ err.Name _ ", " _ err.Location) }
$$$TRACE("Order id insert status "_tSC)
Quit:$$$ISERR(tSC) tSC
}Else { $$$TRACE("Order id '"_pRequest.OrderId_"' and TestId '"_pRequest.TestId_"' combination already exists, so updating the record")
//update the Post db flag $$$TRACE("Inside serviced date update")
Set tOrdUpdateQuery="UPDATE POST.EXTERNALORDERS SET SERVICEDDATE= ? , SERVICED = ?,ACTIVE = ? WHERE ORDERID= ? AND TESTID = ?" Set tSC =..Adapter.ExecuteUpdate(.RowsAffectedOrd,tOrdUpdateQuery,pRequest.ServicedDate,pRequest.Serviced,pRequest.IsActive,pRequest.OrderId,pRequest.TestId) $$$TRACE("Update serviced, active flag status "_tSC_" Rows affected : "_RowsAffectedOrd)
}
Quit tSC
